<div class="field"><label for="access_profile_id">Permission profile</label><select name="access_profile_id" id="access_profile_id"><option value="">Custom permissions below</option>@foreach(\App\Models\HelpdeskRecord::ofKind('roles')->active()->orderBy('name')->get() as $profile)<option value="{{ $profile->id }}" @selected((int)old('access_profile_id',$editing?->access_profile_id)===$profile->id)>{{ $profile->name }}</option>@endforeach</select><small class="muted">A profile inherits its permissions dynamically. Client accounts still cannot receive staff permissions.</small></div>
