<script>document.addEventListener('DOMContentLoaded',()=>{const profile=document.getElementById('access_profile_id');const role=document.getElementById('role');function updateProfile(){document.querySelectorAll('input[name="permissions[]"]').forEach(box=>{box.disabled=!!profile.value||role.value==='admin'||(role.value==='user'&&!['tickets.view','tickets.create','tickets.comment'].includes(box.value));});}profile.addEventListener('change',updateProfile);role.addEventListener('change',updateProfile);updateProfile();});</script>
